      pos += len
      return data
  }
  public func readBlobAsPointer() -> UnsafeMutablePointer<UInt8>? {
      let len = Int(readInt32())
      if (len == 0) { return nil }
      let ptr = UnsafeMutablePointer<UInt8>.allocate(capacity: len)
      ptr.initialize(from: bytes.advanced(by: pos), count: len)
      pos += len
      return ptr
  }
  public static func decodeList<T>(_ ptr: UnsafeMutablePointer<UInt8>, readItem: (NitroRecordReader) -> T) -> [T] {
      let r = NitroRecordReader(ptr: ptr)
      let count = r.readInt32()
      var items: [T] = []
      for _ in 0..<count {
          items.append(readItem(r))
      }
      return items
  }
  /// Decodes a list of nullable items.
  /// Wire format: [4B count][for each: 1B hasValue][item bytes (only if hasValue)]
  /// Counterpart: NitroRecordWriter.encodeNullableList / Dart RecordWriter.encodeNullableList.
  public static func decodeNullableList<T>(_ ptr: UnsafeMutablePointer<UInt8>, readItem: (NitroRecordReader) -> T) -> [T?] {
      let r = NitroRecordReader(ptr: ptr)
      let count = r.readInt32()
      var items: [T?] = []
      for _ in 0..<count {
          let hasValue = r.readBool()
          items.append(hasValue ? readItem(r) : nil)
      }
      return items
  }
  /// Decodes a list encoded by Dart's RecordWriter.encodeIndexedList / encodeIndexedPrimitiveList.
  /// Wire format (payload after outer 4B length prefix):
  ///   [int32 count][int64 × count offsets from payload start][item bytes...]
  /// The offset table is skipped; items are read sequentially after it.
  public static func decodeIndexedList<T>(_ ptr: UnsafeMutablePointer<UInt8>, readItem: (NitroRecordReader) -> T) -> [T] {
      let r = NitroRecordReader(ptr: ptr)
      let count = r.readInt32()
      r.pos += Int(count) * 8  // skip Int64 offset table
      var items: [T] = []
      for _ in 0..<count {
          items.append(readItem(r))
      }
      return items
  }
}

/**
 * Protocol for the NitroServerNative module (NativeImpl.cpp).
 * Conform to this in your Swift/ObjC++ source code if you want
 * to delegate from the C++ HybridObject to a Swift implementation.
 * Nitro may call this implementation from any native thread.
 * Keep mutable state thread-safe or marshal work onto your own queue/actor.
 */
public protocol HybridNitroServerNativeProtocol: AnyObject {
    func engineVersion() -> String
    func supportsTls() -> Bool
    func resetNative() -> Void
    func configureServer(config: RawServerConfig) -> Void
    func registerRoute(route: RawRouteConfig) -> RawServerStatus
    func unregisterRoute(method: String, pattern: String) -> RawServerStatus
    func start() -> RawServerStatus
    func stop() -> Void
    func respond(requestId: Int64, status: Int64, headers: [RawHeader], body: Data) -> Void
    func ackBody(requestId: Int64, ackedChunks: Int64) -> Void
    func startStream(requestId: Int64, status: Int64, headers: [RawHeader]) -> Void
    func sendStreamChunk(requestId: Int64, chunk: Data, last: Bool) -> Void
    func wsSend(connectionId: Int64, payload: Data, binary: Bool) -> Void
    func wsClose(connectionId: Int64, code: Int64) -> Void
    var incomingRequests: AnyPublisher<RawIncomingRequest, Never> { get }
    var bodyChunks: AnyPublisher<RawBodyChunk, Never> { get }
    var serverEvents: AnyPublisher<RawServerEvent, Never> { get }
    var wsMessages: AnyPublisher<RawWsMessage, Never> { get }
}

public class NitroServerNativeRegistry {
    public static var impl: HybridNitroServerNativeProtocol?

    public static func register(_ impl: HybridNitroServerNativeProtocol) {
        NitroServerNativeRegistry.impl = impl
    }

    // Stream: incomingRequests cancellables keyed by dartPort
    public static var _incomingRequestsCancellables = [Int64: AnyCancellable]()

    // Stream: bodyChunks cancellables keyed by dartPort
    public static var _bodyChunksCancellables = [Int64: AnyCancellable]()

    // Stream: serverEvents cancellables keyed by dartPort
    public static var _serverEventsCancellables = [Int64: AnyCancellable]()

    // Stream: wsMessages cancellables keyed by dartPort
    public static var _wsMessagesCancellables = [Int64: AnyCancellable]()
}

